const { parseAmount } = require('./money');

// order: { id, items: [{ sku, price: "12.50", qty }] }
function checkout(order) {
  const totalCents = order.items.reduce((sum, it) => sum + parseAmount(it.price) * it.qty, 0);
  return { orderId: order.id, totalCents };
}

module.exports = { checkout };
// Stand-in for the database layer; only its slow-query warnings show up in the log.
function slowQueryWarning(path) {
  return path.startsWith('/products') ? null : 'no query';
}

module.exports = { slowQueryWarning };
// Parses a user-entered amount such as "12.50" into integer cents.
// Throws Error('Invalid amount: <input>') for input that is not an amount.
function parseAmount(input) {
  const m = String(input).trim().match(/^(\d+)(?:\.(\d{1,2}))?$/);
  const whole = Number(m[1]);
  const frac = m[2] ? Number(m[2].padEnd(2, '0')) : 0;
  return whole * 100 + frac;
}

function formatCents(cents) {
  return (cents / 100).toFixed(2);
}

module.exports = { parseAmount, formatCents };
const { checkout } = require('./checkout');
const { slowQueryWarning } = require('./db');

function log(level, msg) {
  console.log(`${new Date().toISOString()} ${level} ${msg}`);
}

function handle(req) {
  if (req.method === 'POST' && req.path === '/checkout') {
    log('DEBUG', `checkout payload items=${JSON.stringify(req.body.items)}`);
    try {
      const result = checkout(req.body);
      log('INFO', `POST /checkout 200 order=${req.body.id} total=${result.totalCents}`);
      return { status: 200, body: result };
    } catch (e) {
      log('ERROR', `POST /checkout 500 order=${req.body.id} ${e.stack}`);
      return { status: 500, body: { error: 'INTERNAL' } };
    }
  }
  slowQueryWarning(req.path);
  return { status: 404, body: { error: 'NOT_FOUND' } };
}

module.exports = { handle };
const assert = require('assert');
const { parseAmount, formatCents } = require('../src/money');
const { checkout } = require('../src/checkout');

test('parses whole amounts', () => assert.strictEqual(parseAmount('7'), 700));
test('parses cents', () => assert.strictEqual(parseAmount('12.50'), 1250));
test('formats cents', () => assert.strictEqual(formatCents(1250), '12.50'));
test('checkout sums items', () => {
  assert.deepStrictEqual(checkout({ id: 'o1', items: [{ sku: 'A', price: '2.50', qty: 2 }] }), { orderId: 'o1', totalCents: 500 });
});
// Minimal test runner (no dependencies): `node test/run.js` runs every test/*.test.js.
// Tests may be async; each gets 5 s before it counts as hung.
const fs = require('fs');
const path = require('path');

const TIMEOUT_MS = 5000;
const tests = [];
global.test = (name, fn) => tests.push({ name, fn });
for (const f of fs.readdirSync(__dirname).filter((x) => x.endsWith('.test.js')).sort()) {
  require(path.join(__dirname, f));
}

function withTimeout(promise) {
  let timer;
  const timeout = new Promise((_, reject) => { timer = setTimeout(() => reject(new Error(`timed out after ${TIMEOUT_MS} ms`)), TIMEOUT_MS); });
  return Promise.race([promise, timeout]).finally(() => clearTimeout(timer));
}

(async () => {
  let failed = 0;
  for (const t of tests) {
    try {
      await withTimeout(Promise.resolve().then(t.fn));
      console.log(`  ✓ ${t.name}`);
    } catch (e) {
      failed++;
      console.log(`  ✗ ${t.name}`);
      console.log(`    ${String(e && e.message).split('\n').join('\n    ')}`);
    }
  }
  console.log(`\nTests: ${failed} failed, ${tests.length - failed} passed, ${tests.length} total`);
  // Exit explicitly: a hung test may leave timers or promises behind.
  process.exit(failed ? 1 : 0);
})();
