const assert = require('assert');
const { parseAmount } = require('../src/money');
const { handle } = require('../src/server');

// Regression: prices with thousands separators ("1,299.00") crashed parseAmount
// with "Cannot read properties of null (reading '1')", turning POST /checkout into a 500.
test('parses amounts with thousands separators', () => {
  assert.strictEqual(parseAmount('1,299.00'), 129900);
  assert.strictEqual(parseAmount('2,450.50'), 245050);
  assert.strictEqual(parseAmount('1,005.99'), 100599);
  assert.strictEqual(parseAmount('1,000,000'), 100000000);
});

test('rejects malformed amounts with a descriptive error', () => {
  for (const bad of ['abc', '1,29.00', '12,34', '1.234', '']) {
    assert.throws(() => parseAmount(bad), { message: `Invalid amount: ${bad}` });
  }
});

test('POST /checkout succeeds for a comma-formatted price', () => {
  const origLog = console.log;
  console.log = () => {};
  try {
    const res = handle({ method: 'POST', path: '/checkout', body: { id: 'ord_10181', items: [{ sku: 'P-76', price: '1,299.00', qty: 2 }] } });
    assert.strictEqual(res.status, 200);
    assert.deepStrictEqual(res.body, { orderId: 'ord_10181', totalCents: 259800 });
  } finally {
    console.log = origLog;
  }
});
EOF
